package io.github.rivomesh.cdc;

import java.math.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class HiveRowsTest {
    static TableSchema.Column column(TableSchema.Type type){TableSchema.Column c=new TableSchema.Column();c.name="value";c.type=type;return c;}
    @Test void decimalWidthNeverSilentlyRoundsToHivePrecision(){TableSchema.Column c=column(TableSchema.Type.DECIMAL);c.precision=65;c.scale=30;assertEquals("STRING",HiveRows.type(c));String exact="12345678901234567890123456789012345.123456789012345678901234567890";assertEquals(HiveRows.text(exact),HiveRows.value(c,Cell.value(exact)));c.precision=38;c.scale=10;assertEquals("DECIMAL(38,10)",HiveRows.type(c));assertThrows(IllegalArgumentException.class,()->HiveRows.value(c,Cell.value(exact)));}
    @Test void textUsesBase64ExpressionsAndRejectsMalformedUnicode(){String text="'\\\n雪\ud83d\ude03\u0000 OR 1=1";String encoded=HiveRows.text(text);assertFalse(encoded.contains("OR 1=1"));assertFalse(encoded.contains("雪"));assertEquals(text,new String(Base64.getDecoder().decode(encoded.substring(17,encoded.indexOf("'),'UTF-8'"))),java.nio.charset.StandardCharsets.UTF_8));IllegalArgumentException failure=assertThrows(IllegalArgumentException.class,()->HiveRows.text("bad\ud800"));assertFalse(io.github.rivomesh.Sql.retryable(failure));assertEquals("HIVE_TEXT_ENCODING_INVALID",failure.getMessage());}
    @Test void fullImagesNullsAndNativeRangesAreCheckedBeforeSql(){TableSchema.Column c=column(TableSchema.Type.UINT64);assertThrows(IllegalArgumentException.class,()->HiveRows.value(c,Cell.value("18446744073709551616")));assertThrows(IllegalArgumentException.class,()->HiveRows.value(c,Cell.missing()));c.nullable=false;assertThrows(IllegalArgumentException.class,()->HiveRows.value(c,Cell.value(null)));c.type=TableSchema.Type.FLOAT64;assertThrows(IllegalArgumentException.class,()->HiveRows.value(c,Cell.value("NaN")));assertEquals("`_rivomesh_key`",HiveRows.q("_rivomesh_key"));assertThrows(IllegalArgumentException.class,()->HiveRows.q("table;DROP"));}
    @Test void binaryAndJsonRetainTheirDeclaredWireText(){TableSchema.Column c=column(TableSchema.Type.BYTES);assertEquals(HiveRows.text("AP+A"),HiveRows.value(c,Cell.value("AP+A")));assertThrows(IllegalArgumentException.class,()->HiveRows.value(c,Cell.value("%%%")));c.type=TableSchema.Type.JSON;String json="{\"n\":18446744073709551615}";assertEquals(HiveRows.text(json),HiveRows.value(c,Cell.value(json)));}
    @Test void caseInsensitiveStorageRejectsAmbiguousColumnsAndReservedInternals(){TableSchema table=new TableSchema();table.id="id";table.database="sales";table.name="Items";TableSchema.Column upper=column(TableSchema.Type.INT64);upper.name="MixedCase";table.columns=Collections.singletonList(upper);assertEquals("BIGINT",HiveRows.storage(table).get("MixedCase"));TableSchema.Column lower=column(TableSchema.Type.INT64);lower.name="mixedcase";table.columns=Arrays.asList(upper,lower);assertThrows(IllegalArgumentException.class,()->HiveRows.storage(table));table.columns=Collections.singletonList(lower);lower.name="_RIVOMESH_version";assertThrows(IllegalArgumentException.class,()->HiveRows.storage(table));}
}
